style.css:
/* Strawberry Milk */
body { background: #FFF0E8 !important; color: #69454C !important; }
h1, h2, h3 { color: #DB748B !important; }
p { color: #916B70 !important; }
a { color: #D96F8A !important; }
button {
  background: #F4A6B7 !important;
  color: #613C46 !important;
  border: 1px solid #E87891 !important;
  border-radius: 12px !important;
}
input, textarea {
  background: #FADADD !important;
  color: #69454C !important;
  border: 1px solid #EBA5B1 !important;
}
::selection { background: #E87891; color: white; }
